            "easy1_desc": "3차원(3D) 배치로 이미지를 여러 번 편집하다 보면, 물체가 가려지거나 화면 밖으로 나갔다가 다시 들어올 때 원래 생김새를 잃어버리는 일이 생기는데요. 목표 배치는 물체가 어디로 다시 나타나야 하는지는 알려 주지만, 그 생김새는 예전 모습에서 다시 찾아내야만 한다는 거예요. 뭔 소리냐면, 위치는 잡는데 모양이 망가지는 단점이 있다는 말입니다.",
            "easy2_title": "예전 모습을 기억해 뒀다가 다시 나타나게 해 봤습니다",
            "easy2_desc": "그래서 연구진은 LayoutRecall이라는 여러 번 편집하는 편집기를 도입했는데요, 3차원 상자의 지역 좌표계에 생김새를 저장하고 다시 꺼내 쓰는 방식이에요. 상자 표면 잠재 메모리와 기하학 정렬 메모리 조건 조절을 써서 FLUX.2 편집기에 토큰을 공급하고, 일치 손실로 노이즈를 지울 때 맞는 관측을 보게 만들었다는 겁니다. 쉽게 말하면, 예전 기억을 상자마다 담아뒀다가 모양이 흐려질 때 꺼내 쓰는 셈이에요.",
