            "easy1_desc": "종래의 인공신경망은 공간 특징을 모으는 일과 연속적인 물리 시간을 따로 분리해서 다뤄왔는데요, 그러다 보니 규칙적이지 않은 관측 데이터를 제대로 모델링하기가 어려웠다는 한계가 있었습니다. 뭔 소리냐면, 시간 흐름과 공간 정보가 맞물리는 복잡한 상황을 유연하게 받아내지 못했다는 말이에요. 쉽게 말하면, 시공간이 섞이는 문제 앞에서 기존 구조가 뚝뚝 끊어졌다는 셈입니다.",
