            "easy2_desc": "연구진은 이를 해결하려고 다임드 아토믹 웨이브 인테그레이션 뉴런(Damped Atomic Wave Integration Neuron, DAWIN)이라는 새로운 연속 시간 신경망 구성 요소를 제안했는데요, 이 소자는 공간 투영을 경과 시간에 따른 파동 여기와 묶어서 미분 방정식 솔루션 없이도 복소수 상태로 처리할 수 있다고 해요. 그 결과 11가지의 파라미터 맞춤형 작업 중에서 뉴럴 CDE(Neural CDE)보다 9개 작업에서 더 나은 성능을 냈고, 엔비디아(NVIDIA) B200 그래픽처리장치(GPU) 환경에서는 추론 속도를 2630배까지 끌어올렸다는 겁니다. 서브루틴 연산 덕분에 메모리 사용량도 크게 줄어드는 장점이 있는데, 대신 시각 간격을 섞어 버리면 오차가 58.2%에서 77.4%까지 확 늘어난다는 점도 같이 확인됐어요.",
