            "easy1_desc": "연구진은 자율 연구 에이전트가 실험을 반복하며 문제를 해결하는 능력이 커짐에 따라, 이를 평가할 열린 연구 문제와 기존 방식 대비 개선을 측정할 벤치마크가 필요했다고 보았는데요. 이에 따라 5개 과학 분야와 23개 도메인의 100개 열린 연구 문제로 구성된 REE를 도입했다는 겁니다. 모든 문제는 해당 분야의 활발한 연구에서 가져와 전문가 검토를 거쳤다고 하는데요. 쉽게 말하면, AI가 과학 연구를 얼마나 잘 해내는지 공정하게 시험할 수 있는 시험대를 만들었다는 말이에요.",
