            "easy1_desc": "여러 번의 대화로 이루어지는 고용 도우미는 프로젝트와 시간에 따라 변하는 채용 담당자의 취향과 결정 방식을 파악해야 하는데요. 연구진은 대화를 정리하고 관련 사건을 계보에 따라 찾아내는 Open Knowledge Format(OKF) 인덱스 기억 방식을 도입했습니다. 또한 이러한 에피소드에서 프롬프트 반성이나 강화 학습을 거쳐 재사용 가능한 결정 절차를 배우는 Procedure Memory(절차 기억)도 함께 선보였는데요. 쉽게 말하면, 이전 대화들을 구조화해서 필요한 정보를 더 정확히 끄집어내도록 만든 셈이라는 말이에요.",
