            "easy2_desc": "그래서 기존의 기억 없는 방식, 전체 이력 문맥, 대화 검색과 비교해 봤더니, OKF 인덱스 검색은 선호도가 겹치는 조건에서 F1 점수 0.93-0.95를 기록하며 전체 이력보다 훨씬 뛰어난 성능을 보였다고 해요. 절차 기억은 대화 턴 수를 기억 없는 방식에 비해 최대 39% 줄여 주는 장점이 있는데, 대신 모델에 따라 시기별로 중요한 증거를 놓치는 경우도 생간다는 점이 함께 나타난다는 겁니다. 쉽게 말하면, 적은 토큰으로 더 빠르게 대화하면서도 복잡한 추론을 해낼 수 있게 되었다고 보입니다.",
