            "easy1_desc": "연구진은 정직하게 발언한 내용이 나중에 알고 보니 거짓이었을 때, 과연 도덕적으로 철회를 해야 하는지 그 기준을 살펴봤는데요. FIPA-ACL performative disconfirm 방식을 써서 의무론과 결과주의로 발언을 평가하는 믿음 기반 틀을 철회 상황까지 넓혀 봤다는 거예요. 그 결과, 발언 당시의 진실성을 따지는 의무론의 정직 의무만으로는 이미 뱉은 오류를 철회하라고 강제할 수 없다는 걸 증명했다고 하는데요. 뭔 소리냐면, 거짓말은 아니었지만 상대방이 계속 믿게 두면 안 된다는 새로운 지속 의무를 더해야 한다는 말이에요.",
            "easy2_title": "법률 자문 사례로 검토해 봤더니 결과가 어떻게 달라지나",
            "easy2_desc": "그래서 연구진은 답변 세트 프로그래밍(Answer Set Programming)으로 구현한 법률 자문 사례에 이를 적용해 봤는데요. 의무론과 결과주의 모두 철회가 필요하다고 보지만, 피해를 막기에는 너무 늦은 시점이라면 결과주의에서는 더 이상 철회가 필요 없다고 나온다는 겁니다. 철회를 제때 하면 피해를 막는 장점이 있는데, 타이밍을 놓치면 결과주의적 판단이 바뀐다는 점도 같이 따라온다는 거예요. 쉽게 말하면, 언제 철회하느냐에 따라 도덕적 결론이 완전히 달라진 셈이라는 말이에요.",
