            "easy1_title": "첫 토큰만 보고 미래를 가늠해야 하는 상황이었거든요",
            "easy1_desc": "대형 언어 모델(LLM)이 사전 학습이 끝나는 시점에 프롬프트의 키와 값을 지워야 할 때, 앞으로 나올 질문을 모르는 상태에서 무엇을 남길지 정해야만 했는데요. 초안을 미리 만들어 보는 방법이 있긴 한데, 이 과정에서 추가적인 자기회귀 단계가 필요해서 비용이 늘어난다는 단점이 있어요. 그래서 연구진은 첫 번째 출력 토큰의 임베딩을 그대로 활용해 미래의 디코딩 질문을 흉내 내는 저비용 가짜 질문을 만들 수 있을지 시험해 봤다는 겁니다. 쉽게 말하면, 정보가 부족한 상태에서 첫 단추만 보고 다음을 짐작해야 하는 까다로운 상황이었다는 말이에요.",
            "easy2_title": "더 빠르고 나은 쿼리(FBQ) 방식으로 추가 연산을 줄였어요",
            "easy2_desc": "그래서 연구진은 첫 번째 토큰을 여덟 번 복사해서 쓰는 기존의 FTQ-8 방식에서 출발해, 첫 임베딩을 살리면서 나머지 일곱 자리마다 더할 오프셋을 학습시키는 Faster and Better Query(FBQ)를 개발했는데요. 전체 캐시가 있는 상태에서의 평균 프롬프트 주의를 예측하도록 이 오프셋들을 학습시켰다는 겁니다. LongBench 시험에서 FBQ는 여덟 단계의 룩어헤드 Q-캐시와 비슷한 수준의 성능을 보이면서도, 단 한 번의 순방향 패스만으로 모든 프로브 쿼리를 계산해 낸다는 장점이 있어요. 결과적으로 추가 연산 비용을 크게 낮추면서도 필요한 성능을 유지하게 되었다는 셈이에요.",
