            "easy1_desc": "연구진은 AI 코딩 에이전트가 빠르게 코드를 짜 주면서 생기는 검토 부담을 덜기 위해 AI 리뷰어를 붙이는데요, 추론 모델들이 비용과 꼼꼼함을 어떻게 조절하는지 궁금해서 실험해 봤어요. 시험은 통과했지만 더 강한 시험에는 떨어지는 가짜 같은 진짜 코드 패치 90개를 골라서 Claude Opus 5.5, Sonnet 5.5, Haiku 5.5 모델이 각각 낮음, 중간, 높음 노력 수준으로 검토하게 만들었거든요. 그 결과 총 55개는 틀렸고 35개는 맞았다고 합니다. 쉽게 말하면, 노력을 높일수록 틀린 패치를 덜 받아준다는 걸 확인한 셈이에요.",
