            "easy2_desc": "그래서 연구진은 중간 노력이 높은 노력과 비슷한 성능을 내면서 비용을 얼마나 아끼는지 따져봤는데요, Opus 모델은 중간 노력이 높은 노력과 15% 포인트 이내로 차이가 나면서 비용은 20% 줄었다고 해요. 다만 사전 등록했던 목표인 30%에는 조금 못 미쳤다는 단점도 있는데요, Sonnet과 Haiku는 비용을 각각 39%, 51% 줄였지만 성능이 비슷하다는 걸 입증하지는 못했다고 합니다. 쉽게 말하면, 모델마다 비용을 줄이는 효과는 달랐지만 노력을 높일수록 거절하는 능력이 확실히 늘어난다는 거예요.",
