            "easy1_desc": "임베딩 모델이 검색이나 추천에 널리 쓰이지만, 이 모델들의 유사도 판단이 사람이 의미를 이해하는 방식을 그대로 반영하는지 검증할 믿을 만한 방법이 부족했는데요. 기존 벤치마크들은 전문가가 매긴 정적이고 단순한 등급에 기대어 왔기 때문에, 꾸준하고 확실한 데이터를 얻기 어렵고 규모를 키우기도 힘들었다는 거예요. 뭔 소리냐면, 사람이 진짜로 느끼는 바를 반영하는지 평가할 마땅한 기준이 없었다는 말입니다. 결국 기존 방식은 확장성이 떨어지고 일관된 평가가 어렵다는 단점이 있는 셈이에요.",
