            "easy1_desc": "연구진은 다양한 AI 모델과 작업 흐름으로 만들어진 학술 리뷰 속에서, 완전히 AI가 쓴 리뷰와 사람이 쓴 판단을 AI로 다시 쓰기만 한 리뷰를 안정적으로 구별할 수 있는지 살펴봤는데요. 서로 다른 학문 분야의 규칙과 AI 생성 방식을 합친 5,430개의 리뷰로 이루어진 새로운 시험 세트인 PeerShift를 써서 확인해 봤다는 겁니다. 뭔 소리냐면, 단순히 글의 스타일만 보는 게 아니라 여러 복잡한 조건 속에서도 진짜 AI 글을 가려낼 수 있는지 시험해 봤다는 말이에요.",
            "easy2_title": "AI 리뷰를 잡아내는 새로운 탐지기를 만들고 적대적 학습을 더해 성능을 끌어올렸습니다",
