            "easy1_desc": "게임 인공지능(AI)에서 최적의 결정을 찾는 알파-베타 가지치기(alpha-beta pruning)를 쓸 때, 그동안은 가능한 수의 타입 안에 제한 범위를 집어넣느라 방식이 복잡했거든요. 연구진은 그래서 연속자 모나드(continuation monad)와 독서자 모나드(reader monad)를 합친 새로운 방식을 가져와 봤는데요. 수의 타입은 그대로 두고 결과 안쪽에 제한 범위를 기록하는 방식이라 복잡함을 줄였다는 겁니다. 쉽게 말하면, 기존에 쓰이던 선택 모나드(selection monad)의 비효율성을 풀기 위한 새로운 대안을 제시한 셈이에요.",
            "easy2_title": "모나드로 알파-베타 가지치기를 구현해 성능을 크게 높였어요",
            "easy2_desc": "그래서 연구진은 연속자 모나드에 이동 순서까지 더해서 최적의 결과뿐만 아니라 최적의 플레이까지 모두 계산할 수 있음을 보여줬는데요. 틱택토(Tic-Tac-Toe, 삼목 게임) 구현으로 확인해 봤더니, 전체를 다 찾아보는 방식과 비교해서 평가하는 플레이 수가 39배나 줄어드는 결과로 나타났다는 겁니다. 게다가 수학적인 증명을 통해 이 모나드 방식이 기존의 완전 탐색 미니맥스(minimax) 방식과 똑같은 최적의 결과와 플레이를 찾아낸다는 사실을 확인했다고 밝혔어요. 장점은 계산 속도가 엄청나게 빨라진다는 점인데, 대신 표준 모나드 추상화를 깊이 이해해야 한다는 점도 같이 따라온다는 겁니다.",
            "topic": "연속자 모나드와 독서자 모나드를 결합해 알파-베타 가지치기를 새롭게 공식화하고, 그 정확성과 효율성을 증명한 연구예요.",
            "one_line": "모나드 조합으로 알파-베타 가지치기를 새롭게 구현하고 성능을 높였어요.",
