            "easy1_desc": "텍스트를 이미지로 만드는 인공지능(AI) 모델을 한데 모으려고 여러 교사 모델을 하나로 합치는 증류 방식을 쓰는데요, 최근에는 교사 모델을 더 강하게 만들어 학생 모델이 기존보다 더 뛰어난 성능을 내도록 돕는 방법이 쓰이고 있거든요. 그런데 기존 방법들은 얼어붙은 교사 모델과 기준 모델만 바라볼 뿐, 정작 학생 모델이 어떻게 성장하고 있는지는 활용하지 못했다는 단점이 있었어요. 쉽게 말하면, 학생의 현재 실력은 무시하고 교사의 기준만 억지로 주입한 셈이라는 말이에요.",
