            "easy2_desc": "그래서 연구진은 덱스오피디(DexOPD)라는 이중 외삽 기반의 온폴리시 증류(Dual-Extrapolation On-Policy Distillation) 방법을 도입했는데요, 기존처럼 교사 모델을 강하게 밀어내는 동시에 뒤처진 과거의 학생 모델을 기준 삼아 학생 스스로도 한계 밖으로 밀어내도록 만들었어요. 여러 초기 노이즈를 바탕으로 탐색 범위를 넓히고, 작업 보상을 통해 후보 품질의 차이를 정규화된 보조 회귀 방향으로 바꿨다는 거예요. GenEval, OCR, DrawBench 벤치마크에서 시험해 봤더니, 스테이블 디퓨전 3.5 미디엄(SD3.5-Medium) 통합 학생 모델이 젠에발(GenEval) 0.9736, 광학 문자 판독(OCR) 0.9515, 드로우벤치 미학(DrawBench Aesthetic) 6.4875의 점수를 기록하며 기존의 모든 전문가 교사와 기준 모델들을 뛰어넘는 결과를 보였다는 겁니다.",
