            "easy1_desc": "거대한 언어 모델(LLM)을 계속 돌리면 열이 많이 나서 그래픽카드(GPU)가 늙어 망가지고 믿음직스럽지 못하게 된다는 건데요, 온도에 맞춰 일하는 속도를 줄이면 발열은 막지만 속도가 느려지거나 정확도가 떨어지는 문제가 생기거든요. 그래서 연구진은 온도를 낮추면서도 속도와 정확도를 같이 지키는 방법을 찾아보기로 했는데요, 이게 바로 이번 연구에서 풀고자 했던 문제라는 겁니다.",
