            "easy1_desc": "연구진이 AI 에이전트에게 GPU를 쥐여 주고 스스로 AI 연구를 하게 했는데요, GPU가 바쁘게 돌아간다고 해서 일을 잘하고 있는 건 아니라는 걸 확인했어요. 왜냐하면 정작 답을 찾는 데 필요 없는 일로 바쁠 수도 있거든요. 실제로 에이전트가 GPU 시간을 어떻게 쓰는지 살펴봤더니, 필요한 일에는 딱 52%만 썼고, 필요 없는 일에 22%, 그리고 26%는 그냥 놀리고 있었다는 거예요. 쉽게 말하면, GPU를 잔뜩 쥐여 줬는데 절반 가까이는 엉뚱한 데 쓰거나 흘려보낸 셈이라는 말이에요.",
