            "easy2_desc": "그래서 연구진은 프롬프트와 결정론적 코드를 섞은 오픈소스 도구인 ComputeWise를 만들었는데요, 에이전트에게 일을 빨리 끝내라고 하거나 GPU를 계속 바쁘게 돌리라고 시키는 방식으로는 해결이 안 되길래 직접 판을 짰다는 거예요. 이 도구를 다섯 가지 모델에 적용해 봤더니, 정답을 찾는 데 걸리는 불필요한 시간을 80% 이상 덜어냈다는 장점이 있는데요, 대신 에이전트가 스스로 판단하는 과정에 따로 틀을 씌워 줘야 한다는 번거로움도 같이 따라온다는 겁니다.",
