            "easy1_desc": "의료 업무를 자동화하려면 전자의무기록(EHR)의 복잡한 그래픽 사용자 인터페이스(GUI)를 보면서 마우스와 키보드로 정확히 움직이는 비전-언어 에이전트가 필요한데요, 여전히 많은 의료용 에이전트들은 텍스트나 정형화된 도구 호출에만 의존하고 있다는 겁니다. 연구진은 그래서 기존 벤치마크들을 하나로 모아 15,739개의 과제로 이루어진 상호작용 환경인 메드유아이짐(MedUIGym)을 만들어 봤는데요, 스크린샷으로 상태를 파악하고 행동하도록 설계된 환경이라는 말이에요. 쉽게 말하면, 실제 전자의무기록 화면을 보며 임상 업무를 수행하는지 시험해 볼 도구가 부족했다는 셈입니다.",
