            "easy1_desc": "연구진은 텍스트 기반 인공지능 모델에서 프롬프트랑 랜덤 시드를 고정하면 그림이 똑같이 나올 거라고 다들 믿어 왔는데요, 그래픽처리장치(GPU) 환경에서는 그게 통하지 않는다는 걸 확인해 봤습니다. 확산 모델과 자기회귀 모델 등 6개 모델을 여러 수치 정밀도와 세 종류의 GPU 환경에서 최대 100개의 프롬프트로 직접 뜯어봤거든요. 그 결과 시드랑 프롬프트를 똑같이 맞췄어도 단독으로 생성할 때와 배치로 묶어서 돌릴 때의 결과물이 달라진다는 걸 밝혀낸 겁니다. 쉽게 말하면, 똑같은 조건이라도 실행하는 환경이나 GPU 종류에 따라 결과가 완전히 바뀐다는 말이에요.",
