            "easy1_desc": "지금까지의 하드웨어 벤치마크들은 설계 도면부터 시작해서 회로를 앞으로 만들어내는 일만 해왔는데요, 이번 연구진은 그 반대로 이미 만들어진 결과물만 던져주면 인공지능 에이전트가 그걸 보고 제 역할을 할 수 있는지 물어봤다는 겁니다. 그러니까 설계 과정에서 원래 있던 이름이나 구조 같은 정보들이 다 지워진 상태에서, 에이전트가 그 빈틈을 거꾸로 채워낼 수 있는지 시험해 보겠다는 말이에요. 쉽게 말하면, 남이 짜 놓은 코드를 보고 얘가 무슨 짓을 하는지 에이전트가 혼자서 알아낼 수 있는지 파악해 봤다는 셈이에요.",
            "easy2_title": "거꾸로 분석하는 벤치마크를 만들어서 에이전트의 진짜 실력을 뜯어봤다",
