            "easy1_desc": "폐쇄망에서 금융 데이터를 가명 처리하는 직원들을 로컬 대형 언어 모델(LLM)이 돕는데요, 입력이 같은데도 모델이 대답을 매번 다르게 내놓는 경우가 있다는 거예요. 연구진은 그래서 확정된 판정과 수정을 모델 바깥에 두고 정확한 이름 찾기와 학습된 규칙으로 다시 쓰게 만들었는데요. 전문가가 검토할 때는 기관 정책, 국가 개인정보법, 국제 출처 순으로 찾아보도록 워크플로를 짰다는 말이에요. 쉽게 말하면, AI가 오락가락하는 바람에 생기는 혼란을 줄이려고 사람이 확인한 정답을 따로 모아 재활용하는 셈이라는 겁니다.",
