            "easy1_title": "신경망 구조 탐색은 성능이 좋은데 계산 비용이 너무 많이 든다는 문제가 있었는데요",
            "easy1_desc": "다양한 작업에서 최고의 성능을 낸다고 알려진 신경망 구조 탐색(NAS)에는 엄청난 계산 비용이 든다는 한계가 있었거든요. 연구진은 이 문제를 해결하기 위해 사전 학습된 모델을 활용하면서 구조적 가지치기(structured pruning)를 결합한 새로운 프레임워크인 PruneNAS를 도입했습니다. 기존 방식들은 후보 모델을 처음부터 새로 학습시켜야 했다면, 이 방법은 여러 세밀도 수준에서 사전 학습된 네트워크를 가지치기해 후보 풀을 만드는 겁니다. 쉽게 말하면, 처음부터 다시 만드는 대신 기존에 잘 만들어진 모델을 솎아내서 빠르게 최적의 구조를 찾겠다는 말이에요.",
