            "easy1_desc": "트랜스포머 기반 모델들이 언어와 시계열 모델링에서 성능이 좋지만, 셀프 어텐션 연산이 너무 무거워서 자원이 부족한 엣지 가속기에 올리기가 어렵다는 거예요. 연구진은 그래서 가벼우면서도 하드웨어를 고려한 시퀀스 아키텍처인 STEdgeFormer를 제안했는데요. 페어와이즈 셀프 어텐션을 가벼운 인과 집계로 바꿔서 임베디드 신경망 가속기에서 잘 돌아가게 만들었다는 말이에요. 쉽게 말하면, 성능은 챙기면서도 기기에서 실제로 돌릴 수 있게 가볍게 뜯어고친 셈이라는 겁니다.",
