            "easy1_desc": "거대 언어 모델이 만든 금융 분석을 확실하게 검증하려니, 금융 규칙이 주로 자연어로 되어 있어 공식적인 규격이 잘 없다는 문제가 있었는데요. 규칙을 형식화하도록 모델을 학습시키려 해도 라벨이 붙은 데이터가 적고 믿을 만한 훈련 신호가 부족하다는 한계가 컸다는 겁니다. 게다가 민감한 금융 데이터는 외부로 보내기 어렵기 때문에 로컬에서 도는 작은 모델을 선호하게 된다는 말이에요. 쉽게 말하면, 데이터도 부족하고 보안도 챙겨야 하는데 규칙 자체가 복잡해서 그동안 모델을 제대로 가르치기 어려웠던 셈이에요.",
            "easy2_title": "작은 모델도 똑 부러지게 만드는 FormaFin 프레임워크",
            "easy2_desc": "그래서 연구진은 작은 오픈 언어 모델이 금융 규칙을 재사용 가능한 SMT 공식으로 번역하도록 돕는 FormaFin이라는 프레임워크를 선보였는데요. SMT 솔버를 활용해 금융 규칙에 적힌 수치 임계값에서 보상을 계산하고, 여기에 교사 증류와 강화학습을 함께 엮었다는 겁니다. 그 결과 7B 크기의 모델이 자신보다 최대 열 배나 큰 오픈 LLM들을 뛰어넘는 성능을 보여줬다고 하는데요, 기업 대출 모니터링 과제에서 94.8퍼센트의 정확도를 기록했다는 거예요. 다른 LLM들이 낸 분석 오류도 95.6에서 99.7퍼센트까지 잡아낸다는 장점이 있는데, 대신 금융 규칙을 정교하게 공식화하는 과정에 특화되어 있다는 점이 같이 따라온다는 겁니다.",
