            "easy1_desc": "개인용 AI 에이전트(Personal agents)가 일상 업무를 돕는다고 하는데요, 보통은 사용자가 필요한 정보를 완벽하게 준다고 가정하고 성능을 재왔거든요. 그런데 실제로는 정보가 모자라거나, 엉뚱한 내용이 섞여 있거나, 서로 안 맞아서 에이전트가 삐그덕거리는 일이 많다는 겁니다. 그래서 연구진은 불완전한 정보 환경에서 도구를 부르는 효율과 사람과 소통하는 효율을 함께 재는 새로운 기준인 EA-Bench(Efficient Action-Bench)를 만들어 봤다는 말이에요.",
            "easy2_title": "새로운 평가 기준을 만들고 실험해 보니 모델의 허점이 드러났습니다",
            "easy2_desc": "연구진은 기존 벤치마크를 고쳐 63개의 기본 과제를 만들고, 작업 흐름을 방향성 비순환 그래프(DAGs)로 표현해서 정보를 빼거나 엇갈리게 만드는 조건 232가지를 추려냈는데요, 이를 난이도에 따라 쉬운 트랙과 어려운 트랙으로 나눴거든요. 실험해 보니까 불완전한 정보가 정확도를 낮추고 도구 사용 비용을 높인다는 점이 드러났습니다. 더 걱정스러운 점은, 일부 모델이 사용자에게 확인도 안 하고 값을 어림짐작해서 맞는 결과를 낸 것처럼 보였다는 건데요, 이는 정보가 불완전할 때 현재 모델들이 얼마나 믿을 수 없는지 보여준다는 셈이에요.",
