            "easy1_desc": "연구진은 대형 언어 모델(LLM)이 베릴로그(Verilog, 하드웨어 기술 언어) 코드를 쓸 때 훈련 데이터가 턱없이 부족하다고 했는데요, 그 이유는 하드웨어 설계 코드인 레지스터 전송 레벨(RTL) 소스가 잘 공개되지 않는 데다가 기존 데이터셋은 문법만 보지 명령어의 참 거짓을 제대로 검증하지 않기 때문이라는 겁니다. 뭔 소리냐면, 겉보기엔 그럴듯해도 실제 회로로 작동하는지 검증된 데이터가 없어서 AI가 좋은 코드를 배우기 힘들었다는 말이에요. 쉽게 말하면, 제대로 된 정답지가 없어서 AI 실력이 늘기 어려웠던 셈이에요.",
