            "easy2_desc": "그래서 연구진은 베릴로그 데이터셋인 베릴래더(VeriLadder)와 이를 만드는 멀티 에이전트(Multi-Agent) 프레임워크를 개발했는데요, AI 에이전트들이 사양서를 고쳐 쓰고 전자 설계 자동화(EDA) 도구가 통과 여부를 결정하는 방식으로 작동합니다. 이렇게 만든 데이터로 큐웬 이점오 코더(Qwen2.5-Coder-7B-Instruct) 모델을 미세 조정(Fine-tuning)해 봤더니, 베릴로그이발(VerilogEval) v2에서 기능 통과율이 31.7%에서 50.0%로 높아졌다는 겁니다. 서서히 단계를 밟아가며 검증하는 덕분에 데이터의 질이 좋아진다는 장점이 있는데, 대신 여러 에이전트와 도구를 거쳐야 해서 복잡한 과정을 거쳐야 한다는 점도 함께 따라온다는 겁니다.",
