            "easy1_desc": "멀티모달 대형 언어 모델(MLLM) 기반 에이전트가 여러 환경에서 잘 작동하고 있는데요, 문제는 나중에 질문이 나올 때까지 어떤 시각적 증거를 기억해야 할지 모르는 상황에서는 여전히 어려움을 겪는다는 거예요. 뭔 소리냐면, 무슨 디테일이 중요해질지 모르는 채로 일단 다 보고 기억해야 해서 헤맨다는 말이에요. 쉽게 말하면, 시험 문제를 나중에 알려주는데 공부는 미리 다 해야 하는 셈이라는 겁니다.",
