            "easy2_desc": "그래서 연구진은 에보비엠(EvoViM, 자가 진화형 시각 에이전트 프레임워크)이라는 방식을 도입했는데요, 고정된 멀티모달 모델이 상호작용 경험을 바탕으로 메모리와 기술을 담은 하나의 시각 프로그램을 스스로 진화시키는 방식이에요. 실패한 시각적 궤적을 추적해서 증거를 놓치거나 잘못 쓴 부분을 고치고, 분석 도구와 노트까지 스스로 다시 쓴다는 거예요. 기존 최고 기준 모델인 오토메름(AutoMem)과 비교했을 때 6개 작업에서 평균 점수가 31.3에서 47.6점까지 올랐다는 장점이 있는데, 대신 초기 환경 설명만으로는 성능이 훨씬 떨어진다는 한계도 같이 따라온다는 겁니다.",
