            "easy1_desc": "에이전틱 코딩 도구에 보안 요구 사항을 넣었을 때 결과가 어떻게 바뀌는지 살펴봤는데요, 100개의 명세서로 400개의 웹 앱을 만들어 본 결과라는 겁니다. 보안 블록을 붙였더니 앱당 발견된 문제 수가 3분의 1 수준으로 줄어들었다고 해요. 쉽게 말하면, 짧은 문장 하나를 더해 준 것만으로도 전체적인 보안 수준이 눈에 띄게 좋아졌다는 셈이에요.",
