            "easy1_desc": "연구진이 트랜스포머 네트워크를 다음 토큰 예측(NTP, Next-Token Prediction)과 경사 하강법으로 학습시켰더니, 데이터의 인과 관계 순서와 상관없이 왼쪽 맥락에서 인과 관계가 없는 토큰까지 끌어다 쓴다는 사실을 발견했는데요. 왜 이런 문제가 생기는지 그 학습 결함을 낱낱이 파헤쳐 봤다는 거예요. 뭔 소리냐면, 인과 관계가 없는 곁가지 정보까지 잔뜩 섞어서 미래를 예측하게 된다는 말입니다.",
