            "easy1_desc": "과학 연구에 양자 알고리즘을 쓸 수 있을지 찾으려면 전문 지식과 알고리즘 설계 능력이 다 필요한데요, 보통 이 둘을 한 사람이 다 가지고 있기는 힘들거든요. 그래서 연구진은 이 빈틈을 메우려고 실험용 AI 에이전트 파이프라인인 QuASAR를 만들어 봤다는 겁니다. 쉽게 말하면, 서로 다른 분야의 지식을 이어 붙여 줄 도구가 필요했다는 말이에요.",
