            "easy1_desc": "대형 언어 모델(LLM)이 전자상거래 과정에서 고객 상호작용이나 구매 결정을 돕는 글을 쓰는 데 많이 쓰이는데요, 문제는 일반적인 글쓰기 벤치마크만으로는 구조적 제약이나 사용자 요구 같은 실제 사업적 조건을 온전히 담아내지 못한다는 겁니다. 뭔 소리냐면, 범용 평가 방식으로는 전자상거래 현장의 특수한 요구 조건을 제대로 잡아내지 못한다는 말이에요. 결국 실제 현장의 세밀한 능력을 정확히 비교하기가 힘들었다는 겁니다.",
            "easy2_title": "실제 전자상거래 데이터로 만든 벤치마크와 평가 체계를 도입해봤습니다",
            "easy2_desc": "그래서 연구진은 13개 카테고리와 5개 언어에 걸쳐 69개 전자상거래 글쓰기 과제와 3,861개의 실제 쿼리를 담은 EcomWriteBench를 선보였는데요, 인간 피드백을 바탕으로 37가지 능력을 뽑아내어 과제마다 적용할 수 있게 만들었다는 겁니다. 사람들의 선호도를 해석 가능한 채점 기준과 가중치로 바꿔주는 프레임워크도 함께 제안했는데요, 보류된 쿼리에서 사람의 선호도와 88.96% 일치하는 결과를 보여 기존 LLM 심판 방식의 78.54%보다 훨씬 높다는 장점이 있습니다. 대신 다양한 과제와 선호도를 복잡하게 조합해야 한다는 과정상의 까다로움도 함께 따른다는 셈이에요.",
