            "easy1_desc": "요즘 로봇 에이전트는 프로그램과 도구를 써서 스스로 움직임을 바꾸는데요, 이를 모바일 조작 환경에서 제대로 시험하려면 물리적 결과와 상호작용 경험을 이어 주는 가상 세계가 필요했습니다. 하지만 기존에는 에이전트 중심의 실행 결과를 지속해서 받아낼 만한 시뮬레이션 플랫폼이 부족했거든요. 쉽게 말하면, 똑똑한 로봇을 만들고 싶어도 마음껏 굴려 볼 실험장이 마땅치 않았던 셈이에요.",
