            "easy1_desc": "연구진은 LLM(대형 언어 모델) 에이전트가 웹에서 검색하거나 링크를 누를 때, 그 행동 자체가 사용자의 비밀스러운 맥락을 드러낸다는 점에 주목했는데요. 예전의 공격들은 단순하게 네트워크 트래픽을 보거나 프롬프트를 가로채는 방식이어서 방어벽에 쉽게 막혔거든요. 그런데 에이전트가 어떤 페이지를 어떤 순서로 방문하는지 그 행동을 유심히 살펴보면 민감한 정보를 몰래 알아낼 수 있는지 잘 알려지지 않았다는 겁니다. 쉽게 말하면, 에이전트의 사소한 발걸음 자체가 정보 유출의 통로가 된다는 말이에요.",
