            "easy1_desc": "연구진은 두 개의 숨은 층(hidden layer)을 가지고 정수 매개변수(integer parameter)를 쓰는 ReLU 네트워크로 최대값(maximum) 함수를 정확히 나타내는 방법을 살펴봤는데요. 6개 입력의 최대값 함수에서는 가장 작은 양수 출력 배율(output multiplier)이 2라는 것을 확인했고, 7개 입력에서는 2나 6이 된다는 것을 알아냈다는 겁니다. 뭔 소리냐면, 신경망이 입력값의 최대를 정확히 계산하려면 가중치를 어떤 정수로 잡아야 하는지 그 한계를 따져봤다는 말이에요. 이 결과는 정수 입방체 채우기(integral cubical fillings)와 다면체 항등식을 네트워크로 바꾸는 과정을 통해 얻었다고 합니다.",
