            "easy2_desc": "그래서 연구진은 6개 입력 단체(simplex)의 좌표-면 복합체(coordinate-facet complex)에 대해 정수 위에서 6이라는 원추 지수(coning index)를 계산해 냈는데요. 유리수(rational) 표현 가능성과 3-국소(3-local) 표현 가능성을 구별해 주는 유한 특성(finite character)도 함께 만들어 냈다는 겁니다. 이 방식은 비대칭 계수(nonsymmetric coefficients)를 허용하면서도 지정된 사전 안에 머문다는 장점이 있는데요, 대신 저차수 나머지를 다루어야 한다는 조건도 같이 따라온다는 겁니다. 쉽게 말하면, 신경망이 특정 정수 구조를 만족하는지 검증하는 도구를 구체적으로 마련한 셈이에요.",
