            "easy1_desc": "타입 기반 결정 모델(소프트웨어가 바로 쓸 수 있도록 확률이나 옵션을 답하는 모델)은 외부에서 들어오는 텍스트를 입력으로 받는데요, 기존 공격 방식들은 이 위험을 제대로 시험하지 못했거든요. 주입된 지시사항은 잘 먹히지 않고 사실을 덧붙이는 방식은 바뀐 결정이 정당해질 수도 있다는 한계가 있었어요. 연구진은 외부 댓글이 새로운 사실을 전혀 추가하지 않고도 이 모델들이 엉뚱한 결정을 내리도록 설득할 수 있다는 걸 보여줬다는 말이에요. 뭔 소리냐면, 팩트는 그대로인데 말만 살짝 비틀어서 판단을 흔들 수 있다는 겁니다.",
