            "easy1_desc": "물리 시스템용 계획 장치들은 보통 하나의 경로만 찾아내는데요, 이 때문에 예기치 못한 문제가 생기거나 나중에 조건이 바뀌면 대안이 없어진다는 단점이 있어요. 이산적인 계획 분야에서는 최고 품질의 다양한 계획을 세우는 방법들이 있지만, 연속 시간에서는 모든 유효한 경로에 너무 많은 비슷한 복사본들이 생겨서 그대로 쓰기 어렵다는 거예요. 기존의 경로 계획 장치들은 결국 한두 개의 해결책으로 모여 버린다는 말이에요.",
            "easy2_title": "연구진이 내놓은 MPAO는 다른 곳을 찾게 만드는 방식을 썼어요",
            "easy2_desc": "그래서 연구진은 찾은 모든 계획을 다른 곳을 탐색할 단서로 삼는 Many Plans at Once(MPAO)를 내놓았는데요, 경계 조건을 만족하는 신경망을 샘플링하고 검증된 모든 계획을 저장해 언제든 쓸 수 있게 만들었다는 거예요. 다섯 가지 기존 방법들과 같은 예산으로 비교해 봤더니, 네 개 도메인의 40개 문제를 모두 푼 유일한 방법이었다고 보입니다. 접촉이 많은 조작 작업에서는 최고 비용의 25% 이내인 계획을 가장 많이 찾아냈다는 장점이 있는데, 대신 복잡한 구조를 다루는 만큼 학습과 정리에 드는 계산 과정이 복잡해진다는 점도 함께 있다는 겁니다.",
