            "easy1_desc": "인공지능(AI)이 혼자일 때와 둘일 때, 또 사람 평균에 맞춘 AI와 맞춤형 AI를 섞어서 총 168명을 대상으로 아이디어 회의 실험을 해봤는데요. AI가 두 명인 방에서는 게시판에 올라간 아이디어가 늘어난 반면, 사람이 직접 쓴 아이디어는 훅 줄어들었다는 거예요. AI가 한 명일 때는 어떤 AI를 붙였느냐가 중요해서 평균형 AI와 짝을 지었을 때가 가장 활발했는데, 둘이 되면 이 효과가 사라진다는 겁니다. 쉽게 말하면, AI를 늘린다고 해서 사람이 내는 아이디어가 무조건 좋아지지는 않는다는 셈이에요.",
            "easy2_title": "AI 숫자와 성격을 바꾸니 사람들의 참여 방식이 확 달라졌다",
            "easy2_desc": "그래서 연구진은 AI 동료의 수와 구성 방식이 사람이 기여하는 방식을 완전히 바꾼다고 밝혔는데요. AI가 늘어나면 전체적인 다양성은 넓어지지만, 사람이 실제로 게시판에 글을 올리는 비율은 오히려 줄어들기도 한다는 거예요. 단일 AI 실험 결과만 보고 다중 AI 팀에 그대로 적용할 수는 없다는 점을 보여주는데요. 장점은 다양한 관점을 모을 수 있다는 것인데, 대신 AI가 너무 많으면 오히려 사람이 직접 주도하는 비중이 쪼그라든다는 단점도 같이 따라온다는 겁니다.",
